// Prints docs/SETTINGS.md from the settings table, so the reference never drifts from the code:
//   khvr_settings_doc > docs/SETTINGS.md
#include <cstdio>
#include <cstring>
#include <string>

#include "khvr/settings.h"

using namespace khvr;

int main() {
    Settings defaults;
    std::printf("# Settings\n\n"
                "Generated by `khvr_settings_doc` from `core/src/settings.cpp`; do not edit by hand.\n\n"
                "Every option is on the in-headset VR panel (hold the left **Menu** button) and in\n"
                "`/sdcard/Android/data/com.khdays.vr/files/khvr.ini`, which the app rewrites when you\n"
                "close the panel. Each tab is an INI section; values out of range are clamped.\n");
    for (const char *tab : SettingTabs()) {
        std::printf("\n## %s\n\n| Key | Option | Values | Default | Description |\n|---|---|---|---|---|\n", tab);
        for (const SettingDef &d : SettingDefs()) {
            if (std::strcmp(d.tab, tab) != 0) continue;
            std::string values, def;
            switch (d.type) {
            case SettingType::Bool: values = "`true` / `false`"; def = defaults.Bool(d.id) ? "`true`" : "`false`"; break;
            case SettingType::Enum:
                for (size_t i = 0; i < d.optionKeys.size(); ++i)
                    values += (i ? ", " : "") + std::string("`") + d.optionKeys[i] + "`";
                def = std::string("`") + d.optionKeys[defaults.Int(d.id)] + "`";
                break;
            case SettingType::Int:
            case SettingType::Float: {
                char buf[96];
                std::snprintf(buf, sizeof buf, "%g to %g%s%s", d.minValue, d.maxValue, *d.unit ? " " : "", d.unit);
                values = buf;
                std::snprintf(buf, sizeof buf, "`%g`", d.defaultValue);
                def = buf;
                break;
            }
            }
            std::printf("| `%s` | %s | %s | %s | %s |\n", d.key, d.label, values.c_str(), def.c_str(), d.help);
        }
    }
    return 0;
}
